{"path": "packages/conformance/src/registry.ts", "start_line": 1, "end_line": 46, "total_lines": 46, "content": "     1	import {
     2	  type ValidatorFn,
     3	  VALIDATORS,
     4	} from './validators.js';
     5	
     6	export { type ValidatorFn, VALIDATORS };
     7	
     8	/**
     9	 * The registry of named conformance validators. Each validator is keyed by the
    10	 * name the CLI and fixtures refer to; a lookup by name lets an unknown contract
    11	 * name fail fast instead of silently validating against the wrong ruleset.
    12	 */
    13	export class Registry {
    14	  private readonly map = new Map<string, ValidatorFn>();
    15	
    16	  constructor(validators: readonly [string, ValidatorFn][] = VALIDATORS) {
    17	    for (const [name, fn] of validators) {
    18	      if (this.map.has(name)) {
    19	        throw new Error(`duplicate validator registered: ${name}`);
    20	      }
    21	      this.map.set(name, fn);
    22	    }
    23	  }
    24	
    25	  /** Whether a validator with this name exists. */
    26	  has(name: string): boolean {
    27	    return this.map.has(name);
    28	  }
    29	
    30	  /** Look up a validator by name, or throw a typed error if it is unknown. */
    31	  get(name: string): ValidatorFn {
    32	    const fn = this.map.get(name);
    33	    if (!fn) {
    34	      throw new Error(`unknown contract name: ${name}`);
    35	    }
    36	    return fn;
    37	  }
    38	
    39	  /** All registered validator names, in registration order. */
    40	  names(): string[] {
    41	    return [...this.map.keys()];
    42	  }
    43	}
    44	
    45	/** The default registry built from the four contract validators. */
    46	export const registry = new Registry();"}

{"path": "packages/conformance/src/run.ts", "start_line": 1, "end_line": 57, "total_lines": 57, "content": "     1	import { registry } from './registry.js';
     2	import {
     3	  type ContractCard,
     4	  type ConformanceResult,
     5	  type ValidationResult,
     6	} from './types.js';
     7	
     8	/** ANSI helpers for the terminal PASS/FAIL summary. */
     9	const CONFORMANCE_OK = '\x1B[32m'; // green
    10	const CONFORMANCE_WARN = '\x1B[31m'; // red
    11	const RESET = '\x1B[0m';
    12	
    13	/**
    14	 * Run every registered validator over a card.
    15	 *
    16	 * Each validator's result is collected; `pass` is true only when every
    17	 * validator returned ok.
    18	 */
    19	export function run(card: ContractCard, contractName: string): ConformanceResult {
    20	  const results: ValidationResult[] = [];
    21	  for (const name of registry.names()) {
    22	    results.push(registry.get(name)(card));
    23	  }
    24	  return {
    25	    contract: card,
    26	    contractName,
    27	    results,
    28	    pass: results.every((r) => r.ok),
    29	  };
    30	}
    31	
    32	/**
    33	 * Render a green/red PASS/FAIL summary to stdout. Each of the four validators
    34	 * gets a line; a single failure is enough to flip the whole gate to red.
    35	 */
    36	export function report(result: ConformanceResult): void {
    37	  const bar = '\u2500'.repeat(64);
    38	  const line = (text: string) => console.log(text);
    39	
    40	  line('');
    41	  line(bar);
    42	  line(`  conformance · ${result.contractName}`);
    43	  line(bar);
    44	
    45	  for (const r of result.results) {
    46	    const tick = r.ok ? '✓' : '✗';
    47	    const colour = r.ok ? CONFORMANCE_OK : CONFORMANCE_WARN;
    48	    line(`  ${colour}${tick}${RESET}  ${r.name.padEnd(14)} ${r.message}`);
    49	  }
    50	
    51	  line(bar);
    52	  const verdict = result.pass ? 'PASS' : 'FAIL';
    53	  const verdictColour = result.pass ? CONFORMANCE_OK : CONFORMANCE_WARN;
    54	  const failed = result.results.filter((r) => !r.ok).length;
    55	  line(`  ${verdictColour}${verdict}${RESET}  — ${result.results.length} validators, ${failed} failed`);
    56	  line('');
    57	}"}

{"path": "packages/conformance/src/types.ts", "start_line": 1, "end_line": 108, "total_lines": 108, "content": "     1	/**
     2	 * The public "one contract" surface, as a standalone card.
     3	 *
     4	 * The broker's single endpoint returns exactly { content, license, settlement
     5	 * receipt } and every terminal decision decodes to one of four classes. This
     6	 * module names that shape so the four validators below can validate a card
     7	 * against it without importing any broker internals.
     8	 *
     9	 * The card is intentionally a superset of FetchOutcome: the audit row records
    10	 * the subset of the outcome the ledger cares about (price + settlementRef), so
    11	 * the card carries those too. The identity claim mirrors
    12	 * IdentityPresentation — the shape the broker surfaces when a KeyRing AND an
    13	 * identity.subject are both present.
    14	 */
    15	
    16	/** The four terminal classes the broker reports on the audit surface. */
    17	export type TerminalKind =
    18	  | 'fulfilled'
    19	  | 'blocked'
    20	  | 'payment-required'
    21	  | 'token-rejected';
    22	
    23	/** An RSL clause as the broker's license engine normalises it (draft field names). */
    24	export interface LicenseClauseCard {
    25	  type: string;
    26	  value?: string | number | boolean;
    27	  params?: Record<string, string | number>;
    28	}
    29	
    30	/** A license terms document, as surfaced on a fulfilled outcome. */
    31	export interface LicenseCard {
    32	  id: string;
    33	  draft?: string;
    34	  title?: string;
    35	  clauses?: LicenseClauseCard[];
    36	}
    37	
    38	/**
    39	 * An identity claim: what the broker records when a KeyRing is present and a
    40	 * subject is known. `keyId` identifies the active key; `pactToken` is the
    41	 * optional PACT attestation the origin may verify (present iff a subject was
    42	 * issued).
    43	 */
    44	export interface IdentityCard {
    45	  keyId: string;
    46	  subject?: string;
    47	  pactToken?: string;
    48	}
    49	
    50	/** One spend line in the settlement receipt. */
    51	export interface SpendLineCard {
    52	  fetchId: string;
    53	  priceMicros: number;
    54	  settlementRef: string;
    55	}
    56	
    57	/** A broker audit card — the public one-contract shape, in record form. */
    58	export interface ContractCard {
    59	  fetchId: string;
    60	  status: 'fulfilled' | 'denied';
    61	  failureClass?: TerminalKind;
    62	  reason: string;
    63	  content?: {
    64	    body: string;
    65	    contentType: string;
    66	    storeable: boolean;
    67	  };
    68	  license?: LicenseCard;
    69	  obligations?: Array<{ clause: string; kind: string; instruction: string }>;
    70	  price?: { unitsMicros: number; currency: string };
    71	  identity?: IdentityCard;
    72	  /** The RSL `Link` header (or bare href) identifying the license, if any. */
    73	  linkHref?: string | null;
    74	  /** The top-level settlement ref, present iff the outcome is fulfilled. */
    75	  settlementRef?: string | null;
    76	  spendLines: SpendLineCard[];
    77	  timestamps: { startedAt: string; completedAt: string };
    78	}
    79	
    80	/** The result of a single validator over the card. */
    81	export interface ValidationResult {
    82	  name: string;
    83	  ok: boolean;
    84	  message: string;
    85	}
    86	
    87	/** The full conformance outcome for one card. */
    88	export interface ConformanceResult {
    89	  contract: ContractCard;
    90	  contractName: string;
    91	  results: ValidationResult[];
    92	  pass: boolean;
    93	}
    94	
    95	/** A named validator. */
    96	export type ValidatorFn = (card: ContractCard) => ValidationResult;
    97	
    98	/**
    99	 * A typed error carrying the failing validator name, so the CLI can print a
   100	 * clean "validator X failed: message" line instead of an uncaught throw.
   101	 */
   102	export class ConformanceError extends Error {
   103	  readonly name: string;
   104	  constructor(name: string, message: string) {
   105	    super(message);
   106	    this.name = name;
   107	  }
   108	}"}

{"path": "packages/conformance/src/cli.ts", "start_line": 1, "end_line": 34, "total_lines": 34, "content": "     1	import { readFileSync } from 'node:fs';
     2	import { report, run } from './run.js';
     3	import type { ContractCard, ConformanceResult } from './types.js';
     4	
     5	/**
     6	 * The entry point CI invokes:
     7	 *
     8	 *   tsx packages/conformance/src/cli.ts <fixturePath> <contractName>
     9	 *
    10	 * Reads + JSON-parses the fixture, resolves the validators by contractName,
    11	 * runs them, reports, and exits 0 on full pass / 1 on any failure.
    12	 */
    13	function main(argv: string[]): number {
    14	  const [fixturePath, contractName] = argv;
    15	
    16	  if (!fixturePath || !contractName) {
    17	    console.error('usage: conformance <fixturePath> <contractName>');
    18	    return 1;
    19	  }
    20	
    21	  let card: ContractCard;
    22	  try {
    23	    card = JSON.parse(readFileSync(fixturePath, 'utf8')) as ContractCard;
    24	  } catch (cause) {
    25	    console.error(`failed to read fixture "${fixturePath}": ${(cause as Error).message}`);
    26	    return 1;
    27	  }
    28	
    29	  const result: ConformanceResult = run(card, contractName);
    30	  report(result);
    31	  return result.pass ? 0 : 1;
    32	}
    33	
    34	process.exit(main(process.argv.slice(2)));"}

{"path": "packages/conformance/src/validators.ts", "start_line": 1, "end_line": 258, "total_lines": 258, "content": "     1	import {
     2	  type ContractCard,
     3	  type TerminalKind,
     4	  type ValidationResult,
     5	} from './types.js';
     6	
     7	/**
     8	 * The four terminal classes the broker reports. Derived in one place so the
     9	 * identity + audit + contract-shape validators agree on the vocabulary.
    10	 */
    11	const TERMINAL_CLASSES: ReadonlySet<string> = new Set<TerminalKind>([
    12	  'fulfilled',
    13	  'blocked',
    14	  'payment-required',
    15	  'token-rejected',
    16	]);
    17	
    18	/** The RSL `rel` the broker reads as the published license-terms link. */
    19	const LICENSE_REL = 'type:license-terms';
    20	
    21	/**
    22	 * A single contract-shape helper, factored out so each message is built once.
    23	 */
    24	function result(name: string, ok: boolean, message: string): ValidationResult {
    25	  return { name, ok, message };
    26	}
    27	
    28	/**
    29	 * Derive a license id from a Link href the same way the broker's RSL engine
    30	 * does: extract the URL, then take its pathname — not the full href. A bare
    31	 * `/r/73` stays `/r/73`; an absolute `https://licenses.example/r/73` collapses
    32	 * to `/r/73`. Query and hash fragments are dropped, matching the engine's
    33	 * `extractLink`/`slugFromUrl`.
    34	 */
    35	function deriveId(href: string): string {
    36	  const brace = href.match(/<([^>]*)>/);
    37	  const url = brace ? brace[1] : href.split(/\s|;/)[0];
    38	  if (!url) return '';
    39	  try {
    40	    return new URL(url).pathname;
    41	  } catch {
    42	    return url;
    43	  }
    44	}
    45	
    46	/** identity — PACT key/pactToken present and structurally consistent. */
    47	function validateIdentity(card: ContractCard): ValidationResult {
    48	  const id = card.identity;
    49	
    50	  // Identity is best-effort, never a gate: an absent PACT is valid.
    51	  if (!id || typeof id.keyId !== 'string' || id.keyId.length === 0) {
    52	    return result('identity', true, 'PACT not presented (identity is best-effort, not a gate)');
    53	  }
    54	
    55	  // When a PACT is present it must be structured consistently. The broker
    56	  // issues a PACT only when a KeyRing AND an identity.subject are both
    57	  // present — so a subject implies a token, and a token implies a subject.
    58	  const hasSubject = typeof id.subject === 'string' && id.subject.length > 0;
    59	  const hasToken = typeof id.pactToken === 'string' && id.pactToken.length > 0;
    60	  if (hasSubject !== hasToken) {
    61	    return result(
    62	      'identity',
    63	      false,
    64	      'a PACT requires both identity.subject and pactToken ' +
    65	        '(subject present=' + hasSubject + ', token present=' + hasToken + ')',
    66	    );
    67	  }
    68	
    69	  return result(
    70	    'identity',
    71	    true,
    72	    'identity PACT consistent (keyId=' +
    73	      id.keyId +
    74	      (id.subject ? ', subject=' + id.subject : '') +
    75	      ')',
    76	  );
    77	}
    78	
    79	/** license — RSL Link resolves, obligations derive, id is the pathname. */
    80	function validateLicense(card: ContractCard): ValidationResult {
    81	  // A license surfaces only on a fulfilled outcome; a denied outcome carries
    82	  // none and is not an error.
    83	  if (card.status !== 'fulfilled') {
    84	    return result('license', true, 'denied — no license to validate');
    85	  }
    86	
    87	  const license = card.license;
    88	  if (!license) {
    89	    return result('license', false, 'a fulfilled outcome must reference its license terms');
    90	  }
    91	  if (typeof license.id !== 'string' || license.id.length === 0) {
    92	    return result('license', false, 'license id is missing');
    93	  }
    94	
    95	  // An RSL `Link` header with rel="type:license-terms" must identify the doc,
    96	  // and the license id must equal the href's pathname, not the full href.
    97	  if (card.linkHref != null && card.linkHref !== '') {
    98	    if (card.linkHref.indexOf(LICENSE_REL) === -1) {
    99	      return result(
   100	        'license',
   101	        false,
   102	        'the RSL Link must carry rel="' +
   103	          LICENSE_REL +
   104	          '" (found: ' +
   105	          card.linkHref +
   106	          ')',
   107	      );
   108	    }
   109	    const derived = deriveId(card.linkHref);
   110	    if (derived !== license.id) {
   111	      return result(
   112	        'license',
   113	        false,
   114	        'license id must equal the Link href pathname (' +
   115	          derived +
   116	          '), not the full href',
   117	      );
   118	    }
   119	  }
   120	
   121	  // Obligations derive from the license: clauses present ⇒ obligations present,
   122	  // one per clause; absent ⇒ no obligations.
   123	  const clauseCount = (license.clauses ?? []).length;
   124	  const obligationCount = (card.obligations ?? []).length;
   125	  if (clauseCount > 0 && obligationCount === 0) {
   126	    return result('license', false, 'license clauses present but no obligations were derived');
   127	  }
   128	  if (clauseCount > 0 && obligationCount !== clauseCount) {
   129	    return result(
   130	      'license',
   131	      false,
   132	      'expected one obligation per clause (' +
   133	        clauseCount +
   134	        '), derived ' +
   135	        obligationCount,
   136	    );
   137	  }
   138	
   139	  return result(
   140	    'license',
   141	    true,
   142	    'license ' +
   143	      license.id +
   144	      ' (' +
   145	      clauseCount +
   146	      (clauseCount === 1 ? ' clause' : ' clauses') +
   147	      ' → ' +
   148	      obligationCount +
   149	      ' obligation' +
   150	      (obligationCount === 1 ? '' : 's') +
   151	      ')',
   152	  );
   153	}
   154	
   155	/** audit/settlement — rows well-formed, the spend sums, valid terminal class. */
   156	function validateSettlement(card: ContractCard): ValidationResult {
   157	  // A denied outcome records no spend: that is correct and passes.
   158	  if (card.status === 'denied') {
   159	    return result('settlement', true, 'denied — no spend recorded');
   160	  }
   161	
   162	  // A fulfilled outcome paid: every spend line needs a price + settlement ref,
   163	  // and the sum must reconcile with the recorded price.
   164	  const rows = card.spendLines ?? [];
   165	  if (rows.length === 0) {
   166	    return result('settlement', false, 'a fulfilled outcome has no spend lines');
   167	  }
   168	  if (card.price == null) {
   169	    return result('settlement', false, 'a fulfilled outcome must carry a price');
   170	  }
   171	
   172	  const spend: number[] = [];
   173	  for (let i = 0; i < rows.length; i += 1) {
   174	    const row = rows[i];
   175	    if (row == null || typeof row.priceMicros !== 'number' || Number.isNaN(row.priceMicros)) {
   176	      return result('settlement', false, 'spend line ' + i + ' has a non-numeric priceMicros');
   177	    }
   178	    if (typeof row.settlementRef !== 'string' || row.settlementRef.length === 0) {
   179	      return result(
   180	        'settlement',
   181	        false,
   182	        'spend line ' + i + ' (' + (row.fetchId ?? '#' + i) + ') has no settlementRef',
   183	      );
   184	    }
   185	    spend.push(row.priceMicros);
   186	  }
   187	
   188	  const summed = spend.reduce((acc, n) => acc + n, 0);
   189	  if (card.price.unitsMicros !== summed) {
   190	    return result(
   191	      'settlement',
   192	      false,
   193	      'spend line sum ' +
   194	        summed +
   195	        ' != recorded price ' +
   196	        card.price.unitsMicros,
   197	    );
   198	  }
   199	
   200	  return result(
   201	    'settlement',
   202	    true,
   203	    'settlement consistent across ' + rows.length + ' line(s), sum ' + summed,
   204	  );
   205	}
   206	
   207	/** contract-shape (gateway) — outcome shape, terminal class, denied class. */
   208	function validateContractShape(card: ContractCard): ValidationResult {
   209	  if (card.status === 'fulfilled') {
   210	    // Fulfilled releases content + license + a settlement proof.
   211	    if (!card.content || typeof card.content.body !== 'string') {
   212	      return result('contract-shape', false, 'content block is missing/invalid');
   213	    }
   214	    if (!card.license) {
   215	      return result('contract-shape', false, 'license block is missing');
   216	    }
   217	    if (card.settlementRef == null || card.settlementRef.length === 0) {
   218	      return result('contract-shape', false, 'a fulfilled outcome must carry a settlementRef');
   219	    }
   220	  } else {
   221	    // Denied has no content/license/settlement — it must carry a failureClass.
   222	    if (card.failureClass == null || card.failureClass.length === 0) {
   223	      return result('contract-shape', false, 'a denied outcome must carry a failureClass');
   224	    }
   225	  }
   226	
   227	  // The terminal decision must be one of the four classes.
   228	  const terminal = card.status === 'fulfilled' ? 'fulfilled' : card.failureClass;
   229	  if (terminal == null || !TERMINAL_CLASSES.has(terminal)) {
   230	    return result(
   231	      'contract-shape',
   232	      false,
   233	      'decision is not one of the 4 terminal classes: ' + JSON.stringify(terminal),
   234	    );
   235	  }
   236	
   237	  return result(
   238	    'contract-shape',
   239	    true,
   240	    'contract shape OK (' +
   241	      (card.status === 'fulfilled' ? 'fulfilled' : card.failureClass) +
   242	      ')',
   243	  );
   244	}
   245	
   246	/** A conformance validator: one named predicate over the contract card. */
   247	export type ValidatorFn = (card: ContractCard) => ValidationResult;
   248	
   249	/**
   250	 * The four validators, keyed to the public one-contract surface. Each reads
   251	 * the card as plain data — no broker internals are imported.
   252	 */
   253	export const VALIDATORS: ReadonlyArray<[string, ValidatorFn]> = [
   254	  ['identity', validateIdentity],
   255	  ['license', validateLicense],
   256	  ['settlement', validateSettlement],
   257	  ['contract-shape', validateContractShape],
   258	];"}

