    14	/** Random fetch ids (rfc9562-style ULID would be a drop-in upgrade). */
    15	export function makeFetchId(rand: () => number = Math.random): string {
    16	  const alphabet = '0123456789';
    17	  let id = '';
    18	  for (let i = 0; i < 16; i++) id += alphabet[Math.floor(rand() * 16)]!;
    19	  return `fetch_${id}`;
    20	}
